package com.franco.desco.application.evaluation.service;import com.franco.desco.application.evaluation.*;import com.franco.desco.application.evaluation.port.in.EvaluationUseCase;import com.franco.desco.application.evaluation.port.out.EvaluationPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.evaluation.EvaluationModels;
public final class EvaluationApplicationService implements EvaluationUseCase{private final EvaluationPersistencePort p;public EvaluationApplicationService(EvaluationPersistencePort p){this.p=p;}public AppResult<PageResult<EvaluationModels.Summary>>list(EvaluationCommands.ListEvaluations c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.list(c,i,m),"EVALUACIONES_LISTADAS","EVALUACIONES_NO_LISTADAS",AppStatus.BAD_REQUEST);}public AppResult<EvaluationModels.Detail>get(EvaluationCommands.Get c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.get(c,i,m),"EVALUACION_CONSULTADA","EVALUACION_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}public AppResult<Long>create(EvaluationCommands.Create c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.create(c,i,m),"EVALUACION_REGISTRADA","EVALUACION_NO_REGISTRADA");}public AppResult<Void>update(EvaluationCommands.Update c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.update(c,i,m),"EVALUACION_ACTUALIZADA","EVALUACION_NO_ACTUALIZADA",AppStatus.BAD_REQUEST);}public AppResult<Void>registerDryMatter(EvaluationCommands.RegisterDryMatter c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.registerDryMatter(c,i,m),"MATERIA_SECA_REGISTRADA","MATERIA_SECA_NO_REGISTRADA",AppStatus.BAD_REQUEST);}}
